import { createQuote } from './factory.js';
export function handleFare(cents: number) {
  const quote = createQuote('display');
  return quote(cents);
}

files.src/factory.ts:
import { displayAdapter, ledgerAdapter } from './adapters.js';
export function createQuote(mode: string) {
  return mode === 'display' ? displayAdapter() : ledgerAdapter();
}

